// CTP via Const Expression Evaluation
constexpr int power(int base, int exp) {
    int res = 1;
    for (int i = 0; i < exp; ++i) res *= base;
    return res;
}
// Compiler performs full execution here, result is hardcoded:
const int COMPILED_VAL = power(2, 8); // 256

// CTP via Type Specialization (if constexpr, C++17)
template <typename T>
auto execute_ctp(T arg) {
    // Compiler selects branch based on known type, eliminating runtime dispatch
    if constexpr (std::is_integral_v<T>) {
        return arg * 2; // Path 1 selected
    } else {
        return arg.calculate(); // Path 2 selected
    }
}
int result = execute_ctp(5);
// Runtime overhead (vtable lookup) is avoided.
